import { supabase } from '@/integrations/supabase/client'

export const DEV_SUPERADMIN_EMAIL = 'dev-superadmin@xcamp.local'
export const DEV_SUPERADMIN_PASSWORD = 'dev-superadmin-xcamp-2026'

let inFlight: Promise<void> | null = null

/**
 * Dev-only: ensure we're signed in as the seeded super_admin account.
 * Idempotent + de-duplicated. No-op in production builds.
 */
export async function ensureDevSuperadminSession(): Promise<void> {
  if (!import.meta.env.DEV) return
  if (inFlight) return inFlight
  inFlight = (async () => {
    const { data: sess } = await supabase.auth.getSession()
    if (sess.session) return

    const { error: signInErr } = await supabase.auth.signInWithPassword({
      email: DEV_SUPERADMIN_EMAIL,
      password: DEV_SUPERADMIN_PASSWORD,
    })
    if (!signInErr) {
      console.info('[dev-auto-login] signed in as', DEV_SUPERADMIN_EMAIL)
      return
    }

    console.warn('[dev-auto-login] sign-in failed, trying signUp:', signInErr.message)
    const { error: signUpErr } = await supabase.auth.signUp({
      email: DEV_SUPERADMIN_EMAIL,
      password: DEV_SUPERADMIN_PASSWORD,
    })
    if (signUpErr) {
      console.error('[dev-auto-login] signUp failed:', signUpErr.message)
      return
    }
    const { error: retryErr } = await supabase.auth.signInWithPassword({
      email: DEV_SUPERADMIN_EMAIL,
      password: DEV_SUPERADMIN_PASSWORD,
    })
    if (retryErr) {
      console.error(
        '[dev-auto-login] sign-in after signUp failed (likely email confirmation still ON in Supabase):',
        retryErr.message,
      )
    } else {
      console.info('[dev-auto-login] signed up + signed in as', DEV_SUPERADMIN_EMAIL)
    }
  })().finally(() => {
    inFlight = null
  })
  return inFlight
}
